import{_ as t,o,c as r,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"YouTube OAuth Integration & Firestore Learnings","description":"Learnings and rules for Firebase Auth (signInWithPopup vs signInWithRedirect) and Firestore Security Rules.","frontmatter":{"isInternal":true,"type":"Architecture Decision Record","title":"YouTube OAuth Integration & Firestore Learnings","description":"Learnings and rules for Firebase Auth (signInWithPopup vs signInWithRedirect) and Firestore Security Rules.","tags":["auth","youtube","firestore","security-rules","architecture-decision-record"]},"headers":[],"relativePath":"adr/youtube-oauth-integration-learnings.md","filePath":"adr/youtube-oauth-integration-learnings.md"}'),n={name:"adr/youtube-oauth-integration-learnings.md"};function s(a,e,c,d,u,l){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="youtube-oauth-integration-firestore-learnings" tabindex="-1">YouTube OAuth Integration &amp; Firestore Learnings <a class="header-anchor" href="#youtube-oauth-integration-firestore-learnings" aria-label="Permalink to &quot;YouTube OAuth Integration &amp; Firestore Learnings&quot;">​</a></h1><p>This document serves as a reference for AI agents and developers working on this codebase to prevent recurring mistakes regarding Firebase Authentication and Firestore Security Rules, specifically around the YouTube Integration (<code>Integrations.tsx</code>).</p><h2 id="_1-firebase-authentication-signinwithpopup-vs-signinwithredirect" tabindex="-1">1. Firebase Authentication: <code>signInWithPopup</code> vs <code>signInWithRedirect</code> <a class="header-anchor" href="#_1-firebase-authentication-signinwithpopup-vs-signinwithredirect" aria-label="Permalink to &quot;1. Firebase Authentication: `signInWithPopup` vs `signInWithRedirect`&quot;">​</a></h2><p><strong>Problem:</strong> Previously, the app used an <code>AuthCatcher</code> component that opened a new tab (<code>window.open(..., &quot;_blank&quot;)</code>) and called <code>signInWithRedirect</code> to handle the Google OAuth flow for YouTube. This caused the following error when running locally (and sometimes in staging/production):</p><blockquote><p><code>Auth redirect returned without a result. If you are running locally, YouTube connection is only supported in Staging/Production.</code></p></blockquote><p><strong>Why this failed:</strong><code>signInWithRedirect</code> relies on <code>sessionStorage</code> and IndexedDB to maintain auth state across cross-origin redirects. When running locally (e.g., <code>localhost</code>), the redirect bounces through <code>projectId.firebaseapp.com</code> and frequently loses this local storage context, causing <code>getRedirectResult()</code> to return <code>null</code>.</p><p><strong>Solution:</strong> We completely removed the <code>AuthCatcher</code> workaround. The correct and robust approach is to call <code>signInWithPopup(auth, provider)</code> directly inside a button&#39;s <code>onClick</code> handler.</p><ul><li>It naturally opens a secure popup window.</li><li>It is NOT blocked by popup blockers because it is initiated by a direct user click.</li><li>It works flawlessly in local development because it doesn&#39;t require a top-level page redirect that breaks cross-origin session storage.</li></ul><p><em>AI Instruction:</em> <strong>DO NOT</strong> attempt to replace <code>signInWithPopup</code> with <code>signInWithRedirect</code> or implement cross-tab <code>window.open</code> workarounds for OAuth in this app.</p><h2 id="_2-firestore-security-rules-updatedoc-vs-setdoc" tabindex="-1">2. Firestore Security Rules &amp; <code>updateDoc</code> vs <code>setDoc</code> <a class="header-anchor" href="#_2-firestore-security-rules-updatedoc-vs-setdoc" aria-label="Permalink to &quot;2. Firestore Security Rules &amp; `updateDoc` vs `setDoc`&quot;">​</a></h2><p><strong>Problem:</strong> After successful OAuth, the app attempted to save the YouTube token to the user&#39;s document using <code>updateDoc(doc(db, &quot;users&quot;, uid), { ... })</code>. This resulted in a Firebase error:</p><blockquote><p><code>FirebaseError: Missing or insufficient permissions.</code></p></blockquote><p><strong>Why this failed:</strong></p><ol><li><strong>Rule Evaluation Crashes:</strong> The <code>firestore.rules</code> for updating a user document strictly checked that <code>request.resource.data.plan == resource.data.plan</code>. If the user document was newly created and missing the <code>plan</code> field, <code>resource.data.plan</code> resulted in a &quot;missing property&quot; error during rule evaluation. In Firebase Rules, an error defaults to <code>false</code> (access denied).</li><li><strong>Missing Documents:</strong> <code>updateDoc</code> strictly requires the document to already exist. If the backend hadn&#39;t created the user document yet, the operation fails completely.</li></ol><p><strong>Solution:</strong></p><ol><li><strong>Robust Rules:</strong> In <code>firestore.rules</code>, we replaced direct property access with the <code>.get()</code> method equipped with a default value. <ul><li><em>Old:</em> <code>request.resource.data.plan == resource.data.plan</code></li><li><em>New:</em> <code>request.resource.data.get(&#39;plan&#39;, null) == resource.data.get(&#39;plan&#39;, null)</code> This prevents the rules engine from crashing if a field is undefined.</li></ul></li><li><strong>Robust Writes (<code>setDoc</code> with <code>merge: true</code>):</strong> In <code>Integrations.tsx</code>, we switched from <code>updateDoc</code> to <code>setDoc(ref, data, { merge: true })</code> and explicitly provided the <code>uid</code> and <code>email</code>. <ul><li>If the document doesn&#39;t exist, it correctly triggers the <code>create</code> rule (which requires <code>uid</code> and <code>email</code>).</li><li>If the document exists, it correctly triggers the <code>update</code> rule and merges the token fields without overwriting anything else.</li></ul></li></ol><p><em>AI Instruction:</em> <strong>ALWAYS</strong> use <code>.get(&#39;field&#39;, null)</code> in <code>firestore.rules</code> when checking fields that might not exist yet on newly created documents. When writing isolated fields to user documents from the frontend, strongly prefer <code>setDoc(ref, data, { merge: true })</code> over <code>updateDoc</code> to gracefully handle cases where the document has not yet been fully initialized.</p>',17)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
